"""
RLM cost tracking — isolates the *extra* LLM cost introduced by the
`recall_from_memory` tool (the dspy.RLM retrieval calls).

Token usage is captured with dspy's native usage tracker
(`dspy.track_usage()`) wrapped around each RLM call in SmartRetriever.
This is reliable: it does not depend on `lm.history`, which dspy bypasses
because it copies LM objects per call.

Per-task attribution
--------------------
Each task (one ChatSession -> one SmartRetriever) gets a unique `run_id`
from `new_run_id()`. Every recall row carries it, and a `task_total` row
is written when the task ends. Because tau2-bench runs tasks sequentially,
"task N has ended" is detected when task N+1 registers; the final task is
flushed at process exit.

Output: a single CSV (RLM_METRICS_FILE, default ./rlm_metrics.csv) with a
`record_type` column distinguishing per-call `recall` rows from per-task
`task_total` rows.

Pricing is taken solely from the _DEFAULT_PRICE_TABLE in this module
(LiteLLM is not consulted).

Env overrides:
  RLM_METRICS_FILE        path to the CSV metrics file
  RLM_PRICE_INPUT_PER_M   override input  price, USD per 1M tokens
  RLM_PRICE_OUTPUT_PER_M  override output price, USD per 1M tokens
"""
from __future__ import annotations

import csv
import os
import threading
from datetime import datetime

from fastworkflow.utils.rlm_logger import rlm_log
from fastworkflow import task_metrics

# Guards CSV appends.
_LOCK = threading.RLock()

# Per-1M-token prices (input, output). This table is the SINGLE source of
# truth for pricing — LiteLLM is intentionally NOT consulted. Keyed by
# substring match against the model string. Can be overridden per-run via
# RLM_PRICE_INPUT_PER_M / RLM_PRICE_OUTPUT_PER_M.
_DEFAULT_PRICE_TABLE: dict[str, tuple[float, float]] = {
    "gpt-oss-20b": (0.075, 0.30),
}

_CSV_FIELDS = [
    "record_type", "timestamp", "run_id", "session_id",
    "recalls", "input_tokens", "output_tokens", "cost_usd",
    "duration_s", "query",
]

_task_counter = 0


# ---------------------------------------------------------------------------
# Task identity
# ---------------------------------------------------------------------------

def new_run_id() -> str:
    """Return a unique, sortable per-task run id: YYYYMMDD_HHMMSS_taskNNN."""
    global _task_counter
    with _LOCK:
        _task_counter += 1
        return f"{datetime.now().strftime('%Y%m%d_%H%M%S')}_task{_task_counter:03d}"


def register_task(run_id: str, session_id: str = "") -> None:
    """
    Register a task's run_id at SmartRetriever construction.

    Per-task totals are owned by task_metrics (one unified row per task); this
    just signals task identity. The unified module flushes prior tasks when a new
    run_id's first metric arrives, so no explicit flush is needed here.
    """
    return


# ---------------------------------------------------------------------------
# Pricing
# ---------------------------------------------------------------------------

def _lookup_price(model: str) -> tuple[float, float]:
    """Return (input, output) USD-per-1M-token rates for a model.

    The price table is the only source. RLM_PRICE_INPUT_PER_M /
    RLM_PRICE_OUTPUT_PER_M env vars override it if both are set."""
    env_in = os.environ.get("RLM_PRICE_INPUT_PER_M")
    env_out = os.environ.get("RLM_PRICE_OUTPUT_PER_M")
    if env_in and env_out:
        try:
            return float(env_in), float(env_out)
        except ValueError:
            pass
    for key, rates in _DEFAULT_PRICE_TABLE.items():
        if key in (model or ""):
            return rates
    return (0.0, 0.0)


def _compute_cost(model: str, in_tok: int, out_tok: int) -> float:
    """USD cost for a token count, computed solely from the price table.
    LiteLLM is intentionally not consulted — the table holds the correct rates."""
    in_rate, out_rate = _lookup_price(model)
    return in_tok / 1_000_000 * in_rate + out_tok / 1_000_000 * out_rate


# ---------------------------------------------------------------------------
# Recording
# ---------------------------------------------------------------------------

def record_rlm_call(run_id: str, session_id: str | None, query: str,
                    usage_totals: dict, duration_s: float) -> tuple[float, int, int]:
    """
    Record one `recall_from_memory` call.

    `usage_totals` is the output of `dspy.UsageTracker.get_total_tokens()`:
    a map of model-name -> {prompt_tokens, completion_tokens, ...}.

    Appends a `recall` row to the CSV, updates the task accumulator, and
    returns (cost_usd, input_tokens, output_tokens) for this call.
    """
    total_in = 0
    total_out = 0
    total_cost = 0.0
    for model, usage in (usage_totals or {}).items():
        in_tok = int((usage or {}).get("prompt_tokens", 0) or 0)
        out_tok = int((usage or {}).get("completion_tokens", 0) or 0)
        total_in += in_tok
        total_out += out_tok
        total_cost += _compute_cost(model, in_tok, out_tok)

    with _LOCK:
        # Keep the per-recall DETAIL row in rlm_metrics.csv for debugging.
        _append_row({
            "record_type": "recall",
            "timestamp": datetime.now().isoformat(timespec="seconds"),
            "run_id": run_id or "",
            "session_id": session_id or "",
            "recalls": 1,
            "input_tokens": total_in,
            "output_tokens": total_out,
            "cost_usd": round(total_cost, 8),
            "duration_s": round(duration_s, 3),
            "query": (query or "").replace("\n", " ").strip()[:200],
        })

    # Feed the unified per-task metrics (single row per task; task_metrics.csv).
    task_metrics.record(run_id, "rlm", calls=1, input_tokens=total_in,
                        output_tokens=total_out, cost_usd=total_cost,
                        duration_s=duration_s)

    rlm_log(
        f"[RLM COST] recall (run={run_id}): in={total_in} out={total_out} tokens, "
        f"cost=${total_cost:.6f}, {duration_s:.2f}s"
    )
    return total_cost, total_in, total_out


def _append_row(row: dict) -> None:
    """Append one row to the metrics CSV. Caller must hold _LOCK."""
    path = os.environ.get("RLM_METRICS_FILE", "rlm_metrics.csv")
    try:
        exists = os.path.exists(path) and os.path.getsize(path) > 0
        with open(path, "a", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=_CSV_FIELDS)
            if not exists:
                writer.writeheader()
            writer.writerow(row)
    except Exception as e:  # metrics must never break the agent
        rlm_log(f"[RLM COST] failed to write metrics row: {e}")
